-- 던클리 실제 통계 사이트/확장프로그램 반영용 SQL
-- 핵심: API 평균은 season_key='total'만 읽으므로, 합성 데이터도 season_key='total'로 넣습니다.
-- 실행 전 백업 권장:
-- sqlite3 /var/data/data.sqlite ".backup '/var/data/data_before_apply_total_382.sqlite'"
BEGIN TRANSACTION;

-- 기존에 잘못 넣은 별도 시즌 합성 데이터 제거
DELETE FROM duncle_drop_rates WHERE season_key IN ('synthetic_mix_382','synthetic_382','synthetic_live_382');

-- 같은 파일 재실행 시 중복 방지
DELETE FROM duncle_drop_rates WHERE anonymous_id LIKE 'syn_total_382_%' AND season_key='total';

-- 실제 통계/확장프로그램이 읽는 season_key='total'에 추가
COMMIT;
